/**
 * Apply the parsed AME Guide (src/data/guidance/parsed_conditions.json) to the
 * adapted condition catalog. The file is generated by
 * src/apps/web/scripts/build-parsed-conditions.ts — never edit it by hand.
 *
 * - `matched` entries replace the content fields of an existing condition
 *   (pathways, dispositions, checklists, CACI, notes, FAA source) and keep its
 *   id, name and category, so ?condition= URLs, NIH data and form links keep working.
 * - `added` entries are parsed conditions that were not on the site yet.
 */
import type { Condition, ParsedConditionsFile } from './types';

export function applyParsedConditions(
  conditions: Condition[],
  file: ParsedConditionsFile | null | undefined,
): Condition[] {
  const entries = file?.conditions ?? [];
  if (!entries.length) return conditions;

  const matched = new Map(
    entries.filter((e) => e.status === 'matched').map((e) => [e.id, e.fields]),
  );
  const updated = conditions.map((condition) => {
    const fields = matched.get(condition.id);
    if (!fields) return condition;
    return {
      ...condition,
      ...fields,
      id: condition.id,
      name: condition.name,
      category: condition.category,
      relatedMedicationIds: condition.relatedMedicationIds,
    };
  });

  const existingIds = new Set(updated.map((c) => c.id));
  const added = entries
    .filter((e) => e.status === 'added' && !existingIds.has(e.id))
    .map((e) => e.fields as Condition);

  return [...updated, ...added].sort((a, b) => a.name.localeCompare(b.name));
}
